import{S as n,o as e,c as t,a9 as l,B as h}from"./chunks/framework.IJ8axLs_.js";const p="/agentsrc/images/claudecode/06-permission-ladder.svg",k="/agentsrc/images/claudecode/06-classifier-stages.svg",d="/agentsrc/images/claudecode/06-interactive-race.svg",g=JSON.parse('{"title":"Claude Code 权限系统：7 种权限模式与 AI 分类器","description":"","frontmatter":{"title":"Claude Code 权限系统：7 种权限模式与 AI 分类器"},"headers":[],"relativePath":"claudecode/06-permissions.md","filePath":"claudecode/06-permissions.md","lastUpdated":1790217011000}'),r={name:"claudecode/06-permissions.md"},y=Object.assign(r,{setup(o){const i=[{question:"Claude Code 在无沙箱的前提下把安全责任放在权限系统上，其核心决策链的设计哲学是什么？",options:["以 allow 为默认只要任一维度同意就放行操作","deny 优先而 allow 需要各维度共识","完全交由 AI 分类器决策用户全程不参与审批","所有决策退化为用户手动确认不给 AI 放权"],correct:1,explanation:"决策链中 allow 需要模式、规则、分类器都不反对，而 deny 只需要任意一个维度触发。safetyCheck 和内容级 ask 规则甚至 bypass-immune——即使用户开了 bypass 模式也必须触发确认。这种设计在没有沙箱的情况下仍能保证基本安全。"},{question:"auto 模式的 AI 分类器采用两阶段设计（stage 1 fast + stage 2 thinking），其哲学是什么？",options:["stage 1 偏向放行求速度而 stage 2 做严格复核","stage 1 偏向阻止宁可误拦再由 stage 2 复核","两阶段完全独立无信息共享与决策依赖关系","stage 2 纯日志记录用途对实际决策不产生影响"],correct:1,explanation:"stage 1 的 suffix 要求「Err on the side of blocking」，偏向保守阻止；stage 2 要求 review 分类过程确保准确。两阶段消除的是 stage 1 的误拦——block 了实际安全的操作，由 stage 2 推理复核纠正。stage 1 的 allow 没有二次确认，误放行只能靠 stage 1 自身的保守偏向压低概率。"},{question:"AI 分类器构建输入时为什么完全丢弃 assistant 的 text block，只保留 tool_use block？",options:["text block 长度远超 tool_use 不利于分类器快速处理","assistant 文本可被精心构造以绕过分类器安全判定","text block 的推理内容对风险评估没有参考帮助","text block 本质是用户输入变体不应被分类器审视"],correct:1,explanation:"源码注释明确说：assistant 的 text block 是模型自写的，可能被精心构造以影响分类器决策。只保留结构化的 tool_use 调用，把模型的自我辩护排除在外，让分类器只看实际做了什么。"},{question:"denial tracking 的两个计数器（consecutiveDenials 和 totalDenials）分别解决什么问题？",options:["consecutiveDenials 记录日志而 total 上报遥测系统","连续拒绝表明同类操作该停累计拒绝表明整体不满","两者互为冗余任一阈值触发都能退至保守模式","totalDenials 用于限制单次会话的最大推理轮数"],correct:1,explanation:"连续拒绝达 3 次说明这类操作用户不希望 AI 自动做，立即停止自动放行。累计拒绝达 20 次说明用户对 auto 模式整体不满，整个会话退到保守模式。recordSuccess 只重置 consecutiveDenials 不重置 totalDenials，因为前者是短期行为模式，后者是长期用户满意度信号。"},{question:"safetyCheck 类决策（操作 .git/、.claude/、shell 配置）的 bypass-immune 设计意味着什么？",options:["这些路径即使在 bypass 模式下也必须弹窗询问","这些路径只在 auto 模式下询问其他模式直接放行","bypass 模式下跳过询问但会记录完整审计日志","只有 deny 规则命中这些路径时才需要用户确认"],correct:0,explanation:"safetyCheck 覆盖 .git/、.claude/、IDE 配置、shell 配置文件等敏感路径，即使 bypassPermissions 模式、即使 PreToolUse hook 返回了 allow，也必须弹窗。但 classifierApprovable 为 true 时 auto 模式的分类器可以评估放行——跨机器 bridge 消息则为 false，必须强制询问，因为分类器无法判断另一台机器的状态。"}];return(E,s)=>{const a=n("Quiz");return e(),t("div",null,[s[0]||(s[0]=l("",246)),h(a,{questions:i})])}}});export{g as __pageData,y as default};
